																																									local Sg = l:AddLeftGroupbox("Device Spoof")
																																									local Fg = { map = { Mobile = "Mobile", Desktop = "Desktop", Gamepad = "Gamepad On" }, active = false }
																																									local mg = false
																																									local Cg

																																									local function Ng()
																																										if not Cg then
																																											return
																																										end

																																										pcall(function()
																																											if isfunctionhooked(getrawmetatable(game).__namecall) then
																																												restorefunction(getrawmetatable(game).__namecall)
																																											end
																																										end)
																																									end

																																									local Pg = game:GetService("ReplicatedStorage").Remotes.pingEvent
																																									local eg = game:GetService("ReplicatedStorage").Remotes.sbEvent
																																									local jg = game:GetService("ReplicatedStorage").Remotes.deviceEvent
																																									local cg = Instance.new("RemoteEvent")

																																									if isfunctionhooked(cg.FireServer) then
																																										restorefunction(cg.FireServer)
																																									end

																																									local Jg

																																									Jg = hookfunction(cg.FireServer, function(...)
																																										local sg = ...

																																										if rawequal(sg, Pg) then
																																											sg = cg

																																											local lg = table.pack(...)
																																											local Qg = table.pack(Jg(table.unpack(lg, 1, lg.n)))

																																											return table.unpack(Qg, 1, Qg.n)
																																										end

																																										if rawequal(sg, eg) then
																																											local lg = table.pack(...)

																																											if lg[2] == "Travel" then
																																												sg = cg

																																												local Qg = table.pack(Jg(table.unpack(lg, 1, lg.n)))

																																												return table.unpack(Qg, 1, Qg.n)
																																											end
																																										end

																																										if rawequal(sg, jg) then
																																											local lg = table.pack(...)

																																											lg[2] = "Mobile"

																																											local Qg = table.pack(Jg(table.unpack(lg, 1, lg.n)))

																																											return table.unpack(Qg, 1, Qg.n)
																																										end

																																										return Jg(sg, ...)
																																									end)

																																									if isfunctionhooked(getrawmetatable(game).__namecall) then
																																										restorefunction(getrawmetatable(game).__namecall)
																																									end

																																									local Jg

																																									Jg = hookmetamethod(game, "__namecall", function(...)
																																										local sg = ...

																																										if getnamecallmethod() == "FireServer" then
																																											if rawequal(sg, Pg) then
																																												local Pg = table.pack(...)

																																												sg = cg

																																												local lg = table.pack(Jg(table.unpack(Pg, 1, Pg.n)))

																																												return table.unpack(lg, 1, lg.n)
																																											end

																																											if mg and rawequal(sg, eg) then
																																												local Pg = table.pack(...)

																																												if Pg[2] == "Travel" then
																																													sg = cg

																																													local eg = table.pack(Jg(table.unpack(Pg, 1, Pg.n)))

																																													return table.unpack(eg, 1, eg.n)
																																												end
																																											end

																																											if Fg.active and rawequal(sg, jg) then
																																												local Pg = table.pack(...)

																																												Pg[2] = N.P2S3D1 and N.P2S3D1.Value or Pg[2]

																																												local eg = table.pack(Jg(table.unpack(Pg, 1, Pg.n)))

																																												return table.unpack(eg, 1, eg.n)
																																											end
																																										end

																																										return Jg(...)
																																									end)

																																									function Fg.EnsureNamecallHook()
																																										if Cg or Fg.hookPending or not s.CanHookNamecall then
																																											return
																																										end

																																										Fg.hookPending = true
																																										task.spawn(function()
																																											Fg.hookPending = false
																																										end)
																																									end

																																									Sg:AddToggle("P2S3T1", { Text = "Device Spoof", Default = false, Tooltip = "Spoofs your device type.", Callback = function(Cg)
