																																										Z.ResolveCosmeticData = function()
																																											local l = E

																																											if not (l and l.storedData) then
																																												local Mg = i:FindFirstChild("Util")
																																												local Sg = Mg and Mg:FindFirstChild("PlayerData")

																																												if Sg then
																																													local Mg, Lg = pcall(require, Sg)

																																													if Mg then
																																														l = Lg
																																													end
																																												end
																																											end

																																											if l and l.storedData then
																																												return l
																																											end

																																											return nil
																																										end
																																										Z.CosDataOrig = { inv = {}, eq = {}, cfg = {} }
																																										Z.ApplyCosmeticUnlock = function()
																																											local l = Z.ResolveCosmeticData()

																																											if not (l and type(l.storedData.Inventory) == "table") then
																																												return false
																																											end

																																											local Mg = i:FindFirstChild("ShopItems")

																																											if not Mg then
																																												return false
																																											end

																																											local Sg = l.storedData.Inventory
																																											local l = Z.CosDataOrig.inv

																																											for Lg, Lg in ipairs(Mg:GetChildren()) do
																																												if Lg:IsA("Folder") then
																																													for Mg, Mg in ipairs(Lg:GetChildren()) do
																																														if Sg[Mg.Name] == nil then
																																															if l[Mg.Name] == nil then
																																																l[Mg.Name] = false
																																															end

																																															Sg[Mg.Name] = 1
																																														end
																																													end
																																												end
																																											end

																																											return true
																																										end
																																										Z.BuildCosmeticValues = function(l, Mg)
																																											local Sg = l .. "_Default"
																																											local Lg, Cg = {}, {}
																																											local Pg = i:FindFirstChild("ShopItems")
																																											local eg = Pg and Pg:FindFirstChild(l)

																																											if eg then
																																												for l, l in ipairs(eg:GetChildren()) do
																																													if not Cg[l.Name] and l.Name ~= Sg and (Mg == nil or l:IsA("Model") == Mg) then
																																														Cg[l.Name] = true
																																														Lg[#Lg + 1] = l.Name
																																													end
																																												end

																																												table.sort(Lg)
																																											end

																																											table.insert(Lg, 1, Sg)

																																											return Lg
																																										end
																																										Z.ApplyCosmeticSlot = function(l, Mg)
																																											if not Mg or Mg == "" then
																																												return false
																																											end

																																											local Sg = Z.ResolveCosmeticData()

																																											if not Sg then
																																												return false
																																											end

																																											local Lg = Z.CosDataOrig

																																											if type(Sg.storedData.Inventory) == "table" then
																																												if Lg.inv[Mg] == nil then
																																													Lg.inv[Mg] = Sg.storedData.Inventory[Mg] or false
																																												end

																																												Sg.storedData.Inventory[Mg] = 1
																																											end

																																											local Cg = Sg.storedData.Equipping

																																											if type(Cg) == "table" then
																																												for Pg, Pg in ipairs(l) do
																																													if Pg ~= "CourtSkin" then
																																														if Lg.eq[Pg] == nil then
																																															Lg.eq[Pg] = Cg[Pg] or false
																																														end

																																														Cg[Pg] = Mg
																																														pcall(Sg.Changed, "Equipping", Pg)

																																														local Lg = Sg.events and Sg.events.Equipping and Sg.events.Equipping[Pg]

																																														if typeof(Lg) == "Instance" then
																																															pcall(function()
																																																Lg:Fire(Mg)
																																															end)
																																														end
																																													end
																																												end

																																												if l[1] == "CourtSkin" then
																																													Z.RefreshCourtSkins()
																																												end

																																												if l[1] == "Takeover" then
																																													Z.ApplyBodyAura(Mg)
																																												end

																																												if l[1] == "Banner" then
																																													Z.ApplyBanner(Mg)
																																												end
																																											end

																																											return true
																																										end
																																										Z.CosCourtWatch = { current = nil, conn = nil, installed = false }
																																										Z.FindMyCourt = function()
																																											local l = workspace:FindFirstChild("Courts")
																																											local Mg = o:GetAttribute("ActiveCourt")
																																											local Sg = l and type(Mg) == "string" and l:FindFirstChild(Mg) or nil

																																											if Sg then
																																												return Sg
																																											end

																																											local l, Mg = pcall(function()
																																												for Sg, Sg in ipairs(game:GetService("CollectionService"):GetTagged("PlayingPlayers")) do
																																													if Sg.Value == o then
																																														return Sg.Parent.Parent
																																													end
																																												end

																																												return nil
																																											end)

																																											if l then
																																												return Mg
																																											end

																																											return nil
																																										end
																																										Z.PaintCourt = function(l, Mg)
																																											if not l then
																																												return false
																																											end

																																											local Sg = Z.CourtSkinner

																																											if not Sg then
																																												local Lg = o:FindFirstChild("PlayerScripts")
																																												local Cg = Lg and Lg:FindFirstChild("CourtSkinAnimation")
																																												local Lg = Cg and Cg:FindFirstChild("CourtSkinner")

																																												if not Lg then
																																													return false
																																												end

																																												local Cg, Pg = pcall(require, Lg)

																																												if not (Cg and type(Pg) == "table" and type(Pg.changeSkin) == "function") then
																																													return false
																																												end

																																												Sg = Pg
																																												Z.CourtSkinner = Sg
																																											end

																																											local Lg = O(i, "ShopItems")
																																											local Cg = Lg and O(Lg, "CourtSkin")
																																											local Lg = Cg and type(Mg) == "string" and Cg:FindFirstChild(Mg) or nil

																																											if not Lg then
																																												Lg = Cg and Cg:FindFirstChild("CourtSkin_Default")
																																											end

																																											if not Lg then
																																												return false
																																											end

																																											local Mg = Z.ResolveCosmeticData()

																																											if Mg and type(Mg.storedData.Config) == "table" and not Mg.storedData.Config.Toggle_CourtSkins then
																																												local Cg = Z.CosDataOrig.cfg

																																												if Cg.Toggle_CourtSkins == nil then
																																													Cg.Toggle_CourtSkins = false
																																												end

																																												Mg.storedData.Config.Toggle_CourtSkins = true
																																											end

																																											return pcall(function()
																																												task.spawn(Sg.changeSkin, l, Lg, false)
																																											end)
																																										end
																																										Z.RestoreCourt = function(l)
																																											if not l then
																																												return
																																											end

																																											local Mg = O(l, "_CourtSettings")
																																											local Sg = Mg and O(Mg, "CourtSkin")

																																											Z.PaintCourt(l, Sg and Sg.Value or nil)
																																										end
																																										Z.RefreshCourtSkins = function()
																																											local l = N.P4Cos_CourtSkin
																																											local Mg = l and l.Value
																																											local l = type(Mg) == "string" and Mg ~= "" and Mg ~= "CourtSkin_Default"
																																											local Sg = Z.FindMyCourt()
																																											local Lg = Z.CosCourtWatch

																																											if not Lg.installed then
																																												Lg.installed = true
																																												o:GetAttributeChangedSignal("ActiveCourt"):Connect(function()
																																													if Z.RuntimeActive then
																																														task.defer(Z.RefreshCourtSkins)
																																													end
																																												end)
																																											end

																																											if Lg.conn then
																																												pcall(function()
																																													Lg.conn:Disconnect()
																																												end)
																																												Lg.conn = nil
																																											end

																																											if Lg.current and (not l or Lg.current ~= Sg) then
																																												Z.RestoreCourt(Lg.current)
																																												Lg.current = nil
																																											end

																																											if l and Sg then
																																												Z.PaintCourt(Sg, Mg)
																																												Lg.current = Sg

																																												local l = O(Sg, "_CourtSettings")
																																												local Mg = l and O(l, "CourtSkin")

																																												if Mg then
																																													Lg.conn = Mg.Changed:Connect(function()
																																														if Z.RuntimeActive and Z.CosCourtWatch.current == Sg then
																																															task.defer(Z.RefreshCourtSkins)
																																														end
																																													end)
																																												end
																																											end
																																										end
																																										Z.ApplyBodyAura = function(l)
																																											local Mg = o.Character

																																											if not Mg then
																																												return false
																																											end

																																											local Sg = i:FindFirstChild("Util")
																																											local Lg = Sg and Sg:FindFirstChild("TakeoverModule")

																																											if not Lg then
																																												return false
																																											end

																																											local Sg, Cg = pcall(require, Lg)

																																											if not (Sg and type(Cg) == "table" and type(Cg.apply) == "function") then
																																												return false
																																											end

																																											local Sg = nil

																																											if type(l) == "string" and l ~= "" and l ~= "Aura_Default" then
																																												local Lg = O(i, "ShopItems")
																																												local Pg = Lg and O(Lg, "Aura")
																																												local Lg = Pg and O(Pg, l)

																																												Sg = Lg and O(Lg, "Rig") or nil

																																												if not Sg then
																																													return false
																																												end
																																											end

																																											return pcall(function()
																																												task.spawn(Cg.apply, Mg, Sg)
																																											end)
																																										end
																																										Z.CosBannerOrig = nil
																																										Z.ApplyBanner = function(l)
																																											local Mg = o.Character
																																											local Sg = Mg and O(Mg, "HumanoidRootPart")
																																											local Mg = Sg and O(Sg, "NameTag")
																																											local Sg = Mg and O(Mg, "MainFrame")
																																											local Mg = Sg and O(Sg, "Banner")
																																											local Sg = Mg and O(Mg, "UIStroke")

																																											if not (Mg and Sg) then
																																												return false
																																											end

																																											local Lg = Z.CosBannerOrig

																																											if not (type(l) == "string" and l ~= "" and l ~= "Banner_Default") then
																																												if Lg and Lg.inst == Mg then
																																													pcall(function()
																																														Mg:SetAttribute("Animated", Lg.animated)
																																														Sg.Thickness = Lg.thickness
																																														Sg.Transparency = Lg.transparency
																																														Sg.Color = Lg.color
																																														Sg.LineJoinMode = Lg.lineJoin
																																														Sg.ApplyStrokeMode = Lg.strokeMode
																																														Mg.ScaleType = Lg.scaleType
																																														Mg.ImageRectOffset = Lg.rectOffset
																																														Mg.ImageRectSize = Lg.rectSize
																																														Mg.Image = Lg.image
																																													end)
																																												end

																																												Z.CosBannerOrig = nil

																																												return true
																																											end

																																											local Cg = O(i, "ShopItems")
																																											local Pg = Cg and O(Cg, "Banner")
																																											local Cg = Pg and O(Pg, l)
																																											local l = Cg and O(Cg, "UIStroke")

																																											if not (Cg and l) then
																																												return false
																																											end

																																											if not (Lg and Lg.inst == Mg) then
																																												Z.CosBannerOrig = { inst = Mg, image = Mg.Image, scaleType = Mg.ScaleType, rectOffset = Mg.ImageRectOffset, rectSize = Mg.ImageRectSize, animated = Mg:GetAttribute("Animated"), thickness = Sg.Thickness, transparency = Sg.Transparency, color = Sg.Color, lineJoin = Sg.LineJoinMode, strokeMode = Sg.ApplyStrokeMode }
																																											end

																																											return (pcall(function()
																																												Mg:SetAttribute("Animated", Cg:GetAttribute("Animated") and true or false)
																																												Sg.Thickness = l.Thickness
																																												Sg.Transparency = l.Transparency
																																												Sg.Color = l.Color
																																												Sg.LineJoinMode = l.LineJoinMode
																																												Sg.ApplyStrokeMode = l.ApplyStrokeMode

																																												if Cg.ScaleType == Enum.ScaleType.Crop then
																																													Mg.ScaleType = Enum.ScaleType.Crop
																																													Mg.ImageRectOffset = Vector2.new(0, 0)
																																													Mg.ImageRectSize = Vector2.new(0, 0)
																																												else
																																													Mg.ScaleType = Enum.ScaleType.Stretch
																																													Mg.ImageRectOffset = Vector2.new(0, 0)
																																													Mg.ImageRectSize = Vector2.new(512, 102)
																																												end

																																												Mg.Image = Cg.Image

																																												local l = game:GetService("CollectionService")

																																												if not l:HasTag(Mg, "Banners") then
																																													l:AddTag(Mg, "Banners")
																																												end
																																											end))
																																										end
																																										Z.ReapplyCosmeticPicks = function()
