																																																			local bB = X.Legit.LognormalCdf(_B, 0, gg, yg)
																																																			local MB = vg * bB
																																																			local SB = vg * X.Legit.LognormalPdf(_B, 0, gg, yg)

																																																			for vg, vg in ipairs(pg) do
																																																				local yg = X.Legit.LognormalCdf(_B, vg.t0, vg.mu, vg.sigma)

																																																				MB = MB + vg.sign * vg.distance * yg
																																																				SB = SB + vg.distance * X.Legit.LognormalPdf(_B, vg.t0, vg.mu, vg.sigma)
																																																			end

																																																			local vg, yg

																																																			if Dg.axisFirst then
																																																				local pg, gg = X.Legit.AxisShape(MB / Zg, zg, dg, Dg.axisTurn, Dg.axisDrift, Dg.axisPace)

																																																				vg, yg = ig + pg, Hg + gg
																																																			else
																																																				vg = ig + Tg * MB
																																																				yg = Hg + Kg * MB
																																																			end

																																																			local ig = VB * X.Legit.CurvatureProfile(bB)

																																																			vg = vg + Bg * ig
																																																			yg = yg + Xg * ig
																																																			nB = nB + -Dg.ouTheta * nB * YB + Dg.ouSigma * math.sqrt(YB) * Og.Normal(0, 1)
																																																			wB = wB + -Dg.ouTheta * wB * YB + Dg.ouSigma * math.sqrt(YB) * Og.Normal(0, 1)

																																																			local ig = _B / 1000
																																																			local Hg = 1 / (1 + SB * 0.3)
																																																			local Tg = tB * Hg * math.sin(6.283185307179586 * Wg * ig + fB)
																																																			local Kg = tB * Hg * math.sin(6.283185307179586 * Wg * ig + hB)

																																																			Eg[uB] = { x = vg + nB + Tg + Dg.signalNoiseK * SB * Og.Normal(0, 1), y = yg + wB + Kg + Dg.signalNoiseK * SB * Og.Normal(0, 1), t = _B }
																																																		end

																																																		return Eg
																																																	end
																																																	X.Legit.PixelsPerRadian = function(ig)
																																																		local Hg = math.rad(ig.FieldOfView)

																																																		if Hg <= 0.001 then
																																																			return ig.ViewportSize.Y
																																																		end

																																																		return ig.ViewportSize.Y * 0.5 / math.tan(Hg * 0.5)
																																																	end
																																																	X.Legit.AngleTo = function(ig, Hg)
																																																		local Tg = Hg - ig.CFrame.Position

																																																		if Tg.Magnitude < 0.001 then
																																																			return 0
																																																		end

																																																		return math.deg(math.acos(math.clamp(ig.CFrame.LookVector:Dot(Tg.Unit), -1.0, 1)))
																																																	end
																																																	X.Legit.RayOffset = function(ig)
																																																		local Hg = R:GetMouseLocation()
																																																		local Tg = ig.ViewportSize

																																																		return Vector2.new(Hg.X - Tg.X * 0.5, Hg.Y - Tg.Y * 0.5)
																																																	end
																																																	X.Legit.ScreenError = function(ig, Hg, Tg)
																																																		if Tg then
																																																			local Tg = ig:WorldToViewportPoint(Hg)

																																																			if Tg.Z <= 0 then
																																																				return nil
																																																			end

																																																			local Kg = R:GetMouseLocation()

																																																			return Vector2.new(Tg.X - Kg.X, Tg.Y - Kg.Y)
																																																		end

																																																		local Tg = ig.CFrame:PointToObjectSpace(Hg)
																																																		local Hg = X.Legit.PixelsPerRadian(ig)

																																																		if Tg.Z < -0.05 then
																																																			local Kg = -Tg.Z

																																																			return Vector2.new(Tg.X / Kg * Hg, -Tg.Y / Kg * Hg) - X.Legit.RayOffset(ig)
																																																		end

																																																		local Kg = math.sqrt(Tg.X * Tg.X + Tg.Z * Tg.Z)

																																																		return Vector2.new(math.atan2(Tg.X, -Tg.Z) * Hg, -math.atan2(Tg.Y, Kg) * Hg) - X.Legit.RayOffset(ig)
																																																	end
																																																	X.Legit.WantsCursorMode = function()
																																																		local ig = N.P1S8D1 and N.P1S8D1.Value or "Auto"

																																																		if ig == "Cursor Only" then
																																																			return true
																																																		end

																																																		if ig == "Camera Rotation" then
																																																			return false
																																																		end

																																																		return R.MouseBehavior == Enum.MouseBehavior.Default
																																																	end
																																																	X.Legit.ReachBox = 0.9
																																																	X.Legit.ReachSettled = function(ig)
																																																		if not ig.reachPending then
																																																			return true
																																																		end

																																																		if R.MouseBehavior == Enum.MouseBehavior.LockCurrentPosition then
																																																			ig.reachPending = nil
																																																			ig.lastError = nil
																																																			ig.lastDevice = nil

																																																			return true
																																																		end

																																																		if os.clock() - ig.reachPending > 0.25 then
																																																			ig.reachPending = nil

																																																			local Hg = X.Legit.caps

																																																			if Hg and Hg.rightRelease then
																																																				pcall(Hg.rightRelease)
																																																			end

																																																			ig.reachLocked = false
																																																			ig.cursor = true
																																																			ig.autoReach = false
																																																		end

																																																		return false
																																																	end
																																																	X.Legit.UpdateReach = function(ig, Hg, Tg)
																																																		if ig.reachLocked or ig.reachPending or ig.rotate then
																																																			return
																																																		end

																																																		if not ig.autoReach then
																																																			return
																																																		end

																																																		local Kg = Hg:WorldToViewportPoint(Tg)
																																																		local Tg = Hg.ViewportSize

																																																		if Kg.Z > 0 and math.abs(Kg.X - Tg.X * 0.5) <= Tg.X * 0.5 * X.Legit.ReachBox and math.abs(Kg.Y - Tg.Y * 0.5) <= Tg.Y * 0.5 * X.Legit.ReachBox then
																																																			return
																																																		end

																																																		if X.Legit.Rotator() then
																																																			ig.rotate = true
																																																			ig.cursor = false
																																																			ig.skipProfile = true
																																																			ig.lastError = nil
																																																			ig.lastDevice = nil

																																																			return
																																																		end

																																																		local Hg = X.Legit.caps or X.Legit.Refresh()

																																																		if not (Hg.rightPress and pcall(Hg.rightPress)) then
																																																			return
																																																		end

																																																		ig.reachLocked = true
																																																		ig.cursor = false
																																																		ig.reachPending = os.clock()
																																																		ig.skipProfile = true
																																																		ig.lastError = nil
																																																		ig.lastDevice = nil
																																																	end
																																																	X.Legit.ViewportCenter = function()
																																																		local ig = workspace.CurrentCamera
																																																		local Hg = ig and ig.ViewportSize or Vector2.new(1920, 1080)
																																																		local ig = Z.GuiService:GetGuiInset()

																																																		return Hg.X * 0.5 + ig.X, Hg.Y * 0.5 + ig.Y
																																																	end
																																																	X.Legit.CursorPosition = function(ig)
																																																		if R.MouseBehavior == Enum.MouseBehavior.LockCenter then
																																																			return X.Legit.ViewportCenter()
																																																		end

																																																		if ig.position then
																																																			local Hg, Tg = pcall(ig.position)

																																																			if Hg and Tg then
																																																				local ig = Tg.X or Tg.x
																																																				local Hg = Tg.Y or Tg.y

																																																				if tonumber(ig) and tonumber(Hg) then
																																																					return tonumber(ig), tonumber(Hg)
																																																				end
																																																			end
																																																		end

																																																		local ig = R:GetMouseLocation()
																																																		local Hg = Z.GuiService:GetGuiInset()

																																																		return ig.X + Hg.X, ig.Y + Hg.Y
																																																	end
																																																	X.Legit.Step = function(ig, Hg)
																																																		local Tg = X.Legit.session

																																																		if not Tg then
																																																			return nil
																																																		end

																																																		local Kg = X.Legit.caps or X.Legit.Refresh()
																																																		local Dg = Tg.residualX + ig
																																																		local ig = Tg.residualY + Hg
																																																		local Hg = if Dg >= 0 then
																																																			math.floor(Dg)
																																																		else
																																																			math.ceil(Dg)
																																																			local Og = if ig >= 0 then
																																																				math.floor(ig)
																																																			else
																																																				math.ceil(ig)

																																																				Tg.residualX = Dg - Hg
																																																				Tg.residualY = ig - Og

																																																				if Hg == 0 and Og == 0 then
																																																					return nil
																																																				end

																																																				local ig = R.MouseBehavior == Enum.MouseBehavior.LockCurrentPosition
																																																				local Dg = Vector2.new(Hg, Og)
																																																				local zg = pcall(function()
																																																					if Kg.moveRel then
																																																						Kg.moveRel(Hg, Og)
																																																					elseif ig and Kg.move then
																																																						if not Tg.trackedX then
																																																							Tg.trackedX, Tg.trackedY = X.Legit.ViewportCenter()
																																																						end

																																																						Tg.trackedX = Tg.trackedX + Hg
																																																						Tg.trackedY = Tg.trackedY + Og
																																																						Kg.move(math.round(Tg.trackedX), math.round(Tg.trackedY))
																																																					elseif Kg.move then
																																																						local ig, Tg = X.Legit.CursorPosition(Kg)

																																																						Kg.move(math.round(ig) + Hg, math.round(Tg) + Og)
																																																					end
																																																				end)

																																																				return zg and Dg or nil
																																																			end
																																																			X.Legit.Click = function()
																																																				local ig = X.Legit.Refresh()
																																																				local Hg = X.Legit.Flag("P1S8T3", true)

																																																				if ig.press and ig.release then
																																																					local Tg = X.Legit.Opt("P1S8S5", 10) / 1000

																																																					if Hg then
																																																						Tg = math.max(0.012, Tg * Random.new():NextNumber(0.75, 1.3))
																																																					else
																																																						Tg = math.max(0.012, Tg)
																																																					end

																																																					pcall(ig.press)
																																																					task.wait(Tg)
																																																					pcall(ig.release)

																																																					return true
																																																				end

																																																				if ig.click then
																																																					return pcall(ig.click)
																																																				end

																																																				return false
																																																			end
																																																			X.Legit.Stop = function()
																																																				local ig = X.Legit.session

																																																				X.Legit.session = nil
																																																				pcall(function()
																																																					k:UnbindFromRenderStep("__HzLegitAim")
																																																				end)

																																																				if not ig then
																																																					return
																																																				end

																																																				if ig.reachLocked then
																																																					ig.reachLocked = false

																																																					local ig = X.Legit.caps

																																																					if ig and ig.rightRelease then
																																																						pcall(ig.rightRelease)
																																																					end
																																																				end
																																																			end
																																																			X.Legit.IsRunning = function()
																																																				return X.Legit.session ~= nil
																																																			end
																																																			X.Legit.SampleProfile = function(ig, Hg)
																																																				local Tg = ig.profile
																																																				local Kg = ig.index

																																																				while Kg < #Tg and Tg[Kg + 1].t <= Hg do
																																																					Kg = Kg + 1
																																																				end

																																																				ig.index = Kg

																																																				local ig = Tg[Kg]
																																																				local Dg = Tg[Kg + 1]

																																																				if not Dg then
																																																					return ig.p, ig.l, ig.x, ig.y
																																																				end

																																																				local Tg = Dg.t - ig.t
																																																				local Kg = if Tg > 0 then
																																																					math.clamp((Hg - ig.t) / Tg, 0, 1)
																																																				else
																																																					1

																																																					return ig.p + (Dg.p - ig.p) * Kg, ig.l + (Dg.l - ig.l) * Kg, ig.x + (Dg.x - ig.x) * Kg, ig.y + (Dg.y - ig.y) * Kg
																																																				end
																																																				X.Legit.Update = function(ig)
																																																					local Hg = X.Legit.session

																																																					if not Hg then
																																																						return
																																																					end

																																																					Hg.elapsed = Hg.elapsed + (ig or 0)

																																																					if Hg.elapsed > Hg.deadline then
																																																						X.Legit.Stop()

																																																						return
																																																					end

																																																					if not X.Legit.IsEnabled() then
																																																						X.Legit.Stop()

																																																						return
																																																					end

																																																					local ig = workspace.CurrentCamera

																																																					if not ig then
																																																						X.Legit.Stop()

																																																						return
																																																					end

																																																					if Hg.frozen then
																																																						return
																																																					end

																																																					local Tg, Kg = pcall(Hg.resolve)

																																																					if not Tg or typeof(Kg) ~= "Vector3" then
																																																						X.Legit.Stop()

																																																						return
																																																					end

																																																					X.Legit.UpdateReach(Hg, ig, Kg)

																																																					if not X.Legit.ReachSettled(Hg) then
																																																						return
																																																					end

																																																					local Tg = X.Legit.ScreenError(ig, Kg, Hg.cursor)

																																																					if not Tg then
																																																						return
																																																					end

																																																					Hg.error = Tg.Magnitude
																																																					Hg.settled = Hg.error <= Hg.precision

																																																					if Hg.calibrate and Hg.lastDevice and Hg.lastError and Hg.lastDevice.Magnitude >= 2 and not Hg.settled and (Hg.lastCommand or 0) >= 3 then
																																																						local ig = Hg.lastError - Tg
																																																						local Kg = ig:Dot(Hg.lastDevice.Unit) / Hg.lastDevice.Magnitude

																																																						if Kg > 0.002 and Kg < 40 then
																																																							Hg.learned = (Hg.learned or 0) + 1

																																																							local ig = if Hg.learned <= 4 then
																																																								0.6
																																																							else
																																																								0.2

																																																								X.Legit.SetGain(Hg, math.clamp(X.Legit.Gain(Hg) * (1 - ig) + Kg * ig, 0.005, 20))
																																																							end
																																																						end

																																																						Hg.lastError = Tg
																																																						Hg.lastDevice = nil

																																																						if Hg.elapsed < Hg.reaction then
																																																							return
																																																						end

																																																						local ig = (Hg.elapsed - Hg.reaction) * 1000
																																																						local Kg = if Hg.error > 0.001 then
																																																							Tg.Unit
																																																						else
																																																							Vector2.new(1, 0)
																																																							local Dg = Vector2.new(-Kg.Y, Kg.X)
																																																							local Og

																																																							if ig <= Hg.duration and not Hg.skipProfile then
																																																								local zg, dg, Zg, Wg = X.Legit.SampleProfile(Hg, ig)

																																																								if Hg.axisFirst then
																																																									Og = Tg - (Hg.startVec - Vector2.new(Zg, Wg))
																																																								else
																																																									Og = Kg * (Hg.error - Hg.startError * (1 - zg)) + Dg * (dg - Hg.lastLateral)
																																																									Hg.lastLateral = dg
																																																								end
																																																							else
																																																								local ig = Hg.tremor

																																																								if Hg.settled then
																																																									Og = Kg * Hg.rng.Normal(0, 0.22 * ig) + Dg * Hg.rng.Normal(0, 0.22 * ig)
																																																								else
																																																									Og = Kg * (Hg.error * Hg.rng.Uniform(0.3, 0.55)) + Dg * Hg.rng.Normal(0, 0.4 * ig)
																																																								end
																																																							end

																																																							local ig = math.max(Hg.startError * 0.6, 40)

																																																							if Og.Magnitude > ig then
																																																								Og = Og.Unit * ig
																																																							end

																																																							local ig = Og * (Hg.sensitivity / X.Legit.Gain(Hg))

																																																							if ig.Magnitude > 20000 then
																																																								ig = ig.Unit * 20000
																																																							end

																																																							Hg.lastDevice = if Hg.rotate then
																																																								X.Legit.RotateStep(ig.X, ig.Y)
																																																							else
																																																								X.Legit.Step(ig.X, ig.Y)
																																																								Hg.lastCommand = Og.Magnitude
																																																							end
																																																							X.Legit.Begin = function(ig, Hg)
																																																								if not X.Legit.Available() then
																																																									return false
																																																								end

																																																								local Tg = workspace.CurrentCamera

																																																								if not Tg then
																																																									return false
																																																								end

																																																								local Kg, Dg = pcall(ig)

																																																								if not Kg or typeof(Dg) ~= "Vector3" then
																																																									return false
																																																								end

																																																								if X.Legit.AngleTo(Tg, Dg) > X.Legit.Opt("P1S8S1", 180) * 0.5 then
																																																									return false
																																																								end

																																																								local Kg = X.Legit.WantsCursorMode()
																																																								local Og = X.Legit.ScreenError(Tg, Dg, Kg)

																																																								if not Og then
																																																									return false
																																																								end

																																																								X.Legit.Stop()

																																																								local Tg = X.Legit.ResolveConfig()
																																																								local Dg = X.Legit.NewRandom()
																																																								local zg = X.Legit.Generate(0, 0, Og.X, Og.Y, Tg, Dg)
																																																								local dg = math.max(Og.Magnitude, 0.001)
																																																								local Zg, Wg = Og.X / dg, Og.Y / dg
																																																								local Bg = table.create(#zg)

																																																								for Xg, vg in ipairs(zg) do
																																																									Bg[Xg] = { t = vg.t, p = (vg.x * Zg + vg.y * Wg) / dg, l = vg.x * -Wg + vg.y * Zg, x = vg.x, y = vg.y }
																																																								end

																																																								local Zg = X.Legit.Opt("P1S8S4", 0) / 1000

																																																								if Zg > 0 then
																																																									Zg = math.max(0, Zg * Dg.Uniform(0.7, 1.4))
																																																								end

																																																								local Wg = not Kg and X.Legit.Rotator() ~= nil
																																																								local Xg = { resolve = ig, cursor = Kg, rotate = Wg, preAim = Hg == true, profile = Bg, index = 1, duration = zg[#zg].t, startError = dg, startVec = Og, axisFirst = Tg.axisFirst, error = dg, lastLateral = 0, lastError = nil, lastDevice = nil, residualX = 0, residualY = 0, elapsed = 0, reaction = Zg, settled = false, rng = Dg, tremor = math.max(Tg.noise, 0), precision = Tg.precision, sensitivity = math.max(X.Legit.Opt("P1S8S9", 10), 1) / 100, calibrate = X.Legit.Flag("P1S8T2", true), deadline = Zg + math.max(zg[#zg].t / 1000, 0.1) + 3, autoReach = Kg and X.Legit.Flag("P1S8T6", true) and (X.Legit.Rotator() ~= nil or X.Legit.Refresh().rightPress ~= nil and X.Legit.Refresh().rightRelease ~= nil), reachLocked = false, skipProfile = false }

																																																								if not Kg and not Wg and R.MouseBehavior == Enum.MouseBehavior.Default and X.Legit.Flag("P1S8T6", true) then
																																																									local ig = X.Legit.Refresh()

																																																									if ig.rightPress and ig.rightRelease and pcall(ig.rightPress) then
																																																										Xg.reachLocked = true
																																																										Xg.reachPending = os.clock()
																																																									end
																																																								end

																																																								X.Legit.session = Xg
																																																								k:BindToRenderStep("__HzLegitAim", Enum.RenderPriority.Camera.Value + 1, function(ig)
																																																									X.Legit.Update(ig)
																																																								end)

																																																								return true
																																																							end
																																																							X.Legit.Notify = function(ig)
																																																								if not X.Legit.Flag("P1S8T4", false) then
