																																																									local function Dg(Og, dg)
																																																										if Og == nil then
																																																											return false
																																																										end

																																																										if dg and dg.startedPlayers[Og] then
																																																											return true
																																																										end

																																																										for dg, dg in ipairs(W()) do
																																																											local Zg = O(dg, "_CourtSettings")
																																																											local Wg = Zg and O(Zg, "Started")

																																																											if Wg and Wg.Value == true then
																																																												local Zg = O(dg, "_CourtPlayers")

																																																												if Zg then
																																																													for dg, dg in ipairs(Zg:GetChildren()) do
																																																														if z(dg, "ObjectValue") and dg.Value == Og then
																																																															return true
																																																														end
																																																													end
																																																												end
																																																											end
																																																										end

																																																										return false
																																																									end
																																																									local function Og(dg, Zg)
																																																										local Wg = Zg and Zg.courts[dg]

																																																										if Wg and Wg.slots then
																																																											return Wg.slots
																																																										end

																																																										local Zg = dg and O(dg, "_CourtPads")
																																																										local Wg = dg and O(dg, "_CourtPlayers")
																																																										local Bg = og(dg, Zg, Wg)

																																																										return Bg
																																																									end
																																																									local function og(dg, Zg)
																																																										local Wg = 0
																																																										local Bg = Zg and Zg.courts[dg]

																																																										if Bg then
																																																											for dg, dg in ipairs(Bg.occupants or {}) do
																																																												if dg ~= o and not Dg(dg, Zg) then
																																																													Wg = Wg + 1
																																																												end
																																																											end
																																																										end

																																																										return Wg
																																																									end

																																																									function Ig.UpdateQueueLock(dg)
																																																										if Ig.currentTarget == nil then
																																																											return false
																																																										end

																																																										if Ig.queueState == "idle" then
																																																											return false
																																																										end

																																																										if Ig.queueState ~= "awaiting_confirm" and Ig.queueState ~= "await_match_truth" then
																																																											if K(o, "InPad") ~= true then
																																																												D("wait_match_start", "InPad=false with state=" .. Ig.queueState .. " - resetting stale queue state")
																																																												Ig.ResetQueueState(true)
																																																												Ig.phase = "scan_queues"

																																																												return false
																																																											end
																																																										end

																																																										if Ig.queueState == "awaiting_confirm" then
																																																											local dg = ig()

																																																											if dg then
																																																												D("wait_match_start", "confirmed=OptionsFrameV2 text=" .. dg.text)
																																																												Ig.queueState = "in_queue"
																																																												Ig.phase = "wait_match_start"
																																																												Ig.UpdateStatus("confirmed via UI")

																																																												return true
																																																											end

																																																											if K(o, "InPad") == true then
																																																												D("wait_match_start", "confirmed=InPad attribute")
																																																												Ig.queueState = "in_queue"
																																																												Ig.phase = "wait_match_start"
																																																												Ig.UpdateStatus("confirmed on pad")

																																																												return true
																																																											end

																																																											if os.clock() < Ig.queueConfirmUntil then
																																																												Ig.phase = "wait_match_start"
																																																												Ig.UpdateStatus("awaiting pad confirm")

																																																												return true
																																																											end

																																																											D("wait_match_start", "reason=pad_confirm_timeout")
																																																											Ig.ResetQueueState(true)
																																																											Ig.phase = "scan_queues"

																																																											return false
																																																										end

																																																										if Ig.queueState == "await_match_truth" then
																																																											if K(o, "Ingame") == true then
																																																												D("wait_match_start", "match confirmed via Ingame attribute")
																																																												Ig.ResetQueueState(false)

																																																												return false
																																																											end

																																																											if Z.CurrentCamera and Z.CurrentCamera.CameraType == Enum.CameraType.Scriptable then
																																																												D("wait_match_start", "match confirmed via camera Scriptable (cinematic)")
																																																												Ig.ResetQueueState(false)

																																																												return false
																																																											end

																																																											if K(o, "InPad") ~= true then
																																																												D("wait_match_start", "InPad=false during await_match_truth - player left pad")
																																																												Ig.ResetQueueState(true)
																																																												Ig.phase = "scan_queues"

																																																												return false
																																																											end

																																																											local dg = ig()

																																																											if dg and (string.find(dg.text, "Queue") or string.find(dg.text, "Waiting")) then
																																																												D("wait_match_start", "grace interrupted by UI text=" .. dg.text)
																																																												Ig.queueCountdownGraceUntil = 0
																																																												Ig.queueState = "in_queue"
																																																												Ig.phase = "wait_match_start"

																																																												return true
																																																											end

																																																											if os.clock() < Ig.queueCountdownGraceUntil then
																																																												Ig.phase = "wait_match_start"
																																																												Ig.UpdateStatus("awaiting match truth")

																																																												return true
																																																											end

																																																											D("wait_match_start", "reason=stop_countdown_without_match")
																																																											f:Notify({ Title = "Auto Player", Description = "Opponent left - finding new spot", Time = 3 })
																																																											Ig.ResetQueueState(true)
																																																											Ig.phase = "scan_queues"

																																																											return false
																																																										end

																																																										if Ig.queueState == "in_queue" then
																																																											local dg = os.clock() - Ig.queueStateChangedAt

																																																											if dg > 10 then
																																																												local dg = ig()

																																																												if dg then
																																																													Ig.queueStateChangedAt = os.clock()
																																																													D("wait_match_start", "in_queue timeout suppressed - UI still showing: " .. dg.text)
																																																												else
																																																													D("wait_match_start", "reason=in_queue_no_transition_timeout")
																																																													Ig.ResetQueueState(true)
																																																													Ig.phase = "scan_queues"

																																																													return false
																																																												end
																																																											end

																																																											Ig.phase = "wait_match_start"
																																																											Ig.UpdateStatus("in queue")

																																																											return true
																																																										end

																																																										if Ig.queueState == "waiting_for_players" then
																																																											local dg = Ig.queueMaxPlayers > 0 and Ig.queuePlayerCount < Ig.queueMaxPlayers

																																																											if dg then
																																																												if Ig.queueOpponentLostAt == 0 then
																																																													Ig.queueOpponentLostAt = os.clock()
																																																												end

																																																												local dg = os.clock() - Ig.queueOpponentLostAt

																																																												if dg < 5 then
																																																													Ig.phase = "wait_match_start"
																																																													Ig.UpdateStatus(string.format("waiting for opponent %ds", math.ceil(5 - dg)))

																																																													return true
																																																												end

																																																												local Zg = ig()

																																																												if Zg then
																																																													Ig.phase = "wait_match_start"
																																																													Ig.UpdateStatus("waiting - UI still active")

																																																													return true
																																																												end

																																																												D("wait_match_start", string.format("reason=opponent_timeout %.1fs", dg))
																																																												f:Notify({ Title = "Auto Player", Description = "Opponent left - finding new spot", Time = 3 })
																																																												Ig.ResetQueueState(true)
																																																												Ig.phase = "scan_queues"

																																																												return false
																																																											end

																																																											Ig.queueOpponentLostAt = 0
																																																											Ig.phase = "wait_match_start"
																																																											Ig.UpdateStatus(string.format("waiting for players %d/%d", Ig.queuePlayerCount, Ig.queueMaxPlayers))

																																																											return true
																																																										end

																																																										if Ig.queueState == "match_found" or Ig.queueState == "match_countdown" then
																																																											Ig.phase = "wait_match_start"
																																																											Ig.UpdateStatus("countdown " .. tostring(Ig.queueTimer or ""))

																																																											return true
																																																										end

																																																										return false
																																																									end

																																																									local function dg(Zg)
																																																										local Wg = {}

																																																										for Bg, Bg in ipairs(W()) do
																																																											local Xg = Zg and Zg.courts[Bg]
																																																											local vg

																																																											if Xg then
																																																												vg = Xg.started
																																																											else
																																																												local Eg = O(Bg, "_CourtSettings")
																																																												local yg = Eg and O(Eg, "Started")

																																																												vg = yg and yg.Value == true
																																																											end

																																																											if vg == false then
																																																												local vg = Og(Bg, Zg)
																																																												local Zg = Xg and Xg.teamSize or 1

																																																												if Zg == 1 then
																																																													local Xg = {}
																																																													local Eg = nil

																																																													for yg, yg in ipairs(vg) do
																																																														if yg.occupant == o then
																																																															Eg = yg
																																																														elseif yg.occupantName == nil then
																																																															table.insert(Xg, yg)
																																																														end
																																																													end

																																																													local yg = 0

																																																													for pg, pg in ipairs(vg) do
																																																														if pg.occupantName ~= nil and pg.occupant ~= o then
																																																															yg = yg + 1
																																																														end
																																																													end

																																																													if yg >= 1 then
																																																														local vg = Eg or Xg[1]

																																																														if vg and vg.position then
																																																															local Xg = Ig.ResolveQueuePadModel(O(Bg, "_CourtPads"), vg.name)

																																																															table.insert(Wg, { court = Bg, kind = "queue", slot = vg.name, padModel = Xg, padName = Xg and Xg.Name or vg.name, position = vg.position, teamSize = Zg, readyCount = yg, hasOccupant = Eg ~= nil, label = string.format("%s | %s", Bg.Name, vg.name) })
																																																														end
																																																													end
																																																												end
																																																											end
																																																										end

																																																										table.sort(Wg, function(Zg, Bg)
																																																											if Zg.hasOccupant ~= Bg.hasOccupant then
																																																												return Zg.hasOccupant
																																																											end

																																																											if Zg.readyCount ~= Bg.readyCount then
																																																												return Zg.readyCount > Bg.readyCount
																																																											end

																																																											if Zg.teamSize ~= Bg.teamSize then
																																																												return Zg.teamSize < Bg.teamSize
																																																											end

																																																											return Zg.label < Bg.label
																																																										end)

																																																										return Wg
																																																									end
																																																									local function Zg(Wg)
																																																										local Bg = {}

																																																										for Xg, Xg in ipairs(W()) do
																																																											local vg = Wg and Wg.courts[Xg]

																																																											if vg ~= nil then
																																																												local Eg = vg.teamSize
																																																												local yg = vg.gamemode

																																																												if vg.started == true and vg.paused ~= true and Eg == 1 then
																																																													local yg = Og(Xg, Wg)
																																																													local Wg = nil
																																																													local pg = {}

																																																													for gg, gg in ipairs(yg) do
																																																														if gg.occupant == o then
																																																															Wg = gg
																																																														elseif gg.occupantName == nil then
																																																															table.insert(pg, gg)
																																																														end
																																																													end

																																																													local yg = Wg or pg[1]

																																																													if yg and yg.position then
																																																														local Wg = math.max(0, math.floor(tonumber(vg.homeScore) or 0))
																																																														local pg = math.max(0, math.floor(tonumber(vg.awayScore) or 0))

																																																														if not (Wg > 21 and pg > 21) then
																																																															local gg = Ig.ResolveQueuePadModel(O(Xg, "_CourtPads"), yg.name)

																																																															table.insert(Bg, { court = Xg, kind = "live", slot = yg.name, padModel = gg, padName = gg and gg.Name or yg.name, position = yg.position, homeScore = Wg, awayScore = pg, pointsToFinish = Ng(vg.homeScore, vg.awayScore), teamSize = Eg, label = string.format("%s | live %s-%s | %s", Xg.Name, Wg, pg, yg.name) })
																																																														end
																																																													end
																																																												end
																																																											end
																																																										end

																																																										table.sort(Bg, function(Wg, Xg)
																																																											if Wg.pointsToFinish == Xg.pointsToFinish then
																																																												if Wg.teamSize == Xg.teamSize then
																																																													local vg = math.max(Wg.homeScore, Wg.awayScore)
																																																													local Eg = math.max(Xg.homeScore, Xg.awayScore)

																																																													if vg == Eg then
																																																														return Wg.label < Xg.label
