																																																											if kg.Z > 0 then
																																																												return Mg(kg.X, kg.Y), true
																																																											end

																																																											local kg = k.CFrame:PointToObjectSpace(Ag)
																																																											local Ag = math.atan2(kg.Y, kg.X) + 3.141592653589793

																																																											kg = CFrame.Angles(0, 0, Ag):VectorToWorldSpace(CFrame.Angles(0, 1.5690509975429023, 0):VectorToWorldSpace(Sg(0, 0, -1.0)))

																																																											local Ag = eg(k.CFrame:PointToWorldSpace(kg))

																																																											return Mg(Ag.X, Ag.Y), false
																																																										end
																																																										local function Ag(kg, xg)
																																																											local Rg, Ug, ig, og

																																																											for Hg, Hg in ipairs(ag) do
																																																												local Tg = eg((kg * CFrame.new(Hg * xg)).Position)

																																																												if Tg.Z <= 0 then
																																																													return nil
																																																												end

																																																												Rg = Rg and math.min(Rg, Tg.X) or Tg.X
																																																												Ug = Ug and math.min(Ug, Tg.Y) or Tg.Y
																																																												ig = ig and math.max(ig, Tg.X) or Tg.X
																																																												og = og and math.max(og, Tg.Y) or Tg.Y
																																																											end

																																																											return Mg(Rg, Ug), Mg(ig - Rg, og - Ug)
																																																										end
																																																										local function eg(kg, xg, Rg, Ug, ig)
																																																											if not mg.Tracers then
																																																												if kg.Drawings.Tracer then
																																																													kg.Drawings.Tracer.Visible = false
																																																													kg.Drawings.TracerOutline.Visible = false
																																																												end

																																																												return
																																																											end

																																																											local og = Jg(kg, "TracerOutline", "Line", { Thickness = 3, Color = Color3.new(0.05, 0.05, 0.05) })
																																																											local Hg = Jg(kg, "Tracer", "Line", { Thickness = 1 })
																																																											local kg = lg()

																																																											Hg.Transparency = math.clamp(1 - Ug / 500, 0.35, 1) * ig
																																																											Hg.From = kg
																																																											Hg.To = xg
																																																											Hg.Color = Rg
																																																											Hg.Visible = true
																																																											og.Transparency = Hg.Transparency - 0.15
																																																											og.From = kg
																																																											og.To = xg
																																																											og.Visible = true
																																																										end
																																																										local function lg(kg, xg, Rg, Ug)
																																																											local ig = jg(Ug.BoxSize, xg)
																																																											local og, Hg

																																																											if ig then
																																																												og = s(xg)
																																																												Hg = typeof(ig) == "Vector3" and ig or Sg(ig * 0.6, ig, ig * 0.6)
																																																											else
																																																												og, Hg = Qg(xg)
																																																											end

