																																																											end

																																																											if not Qg then
																																																												if kg.Drawings.Box then
																																																													kg.Drawings.Box.Visible = false
																																																													kg.Drawings.BoxOutline.Visible = false
																																																												end

																																																												return nil
																																																											end

																																																											local Ag = jg(Ug.BoxThickness, xg) or 1
																																																											local xg = Jg(kg, "BoxOutline", "Square", { Filled = false, Color = Color3.new(0.05, 0.05, 0.05) })
																																																											local Ug = Jg(kg, "Box", "Square", { Filled = false })

																																																											xg.Thickness = Ag + 2
																																																											xg.Position = Qg
																																																											xg.Size = ig
																																																											xg.Visible = true
																																																											Ug.Thickness = Ag
																																																											Ug.Position = Qg
																																																											Ug.Size = ig
																																																											Ug.Color = Rg
																																																											Ug.Visible = true

																																																											return Qg, ig
																																																										end
																																																										local function Qg(Ag, kg)
																																																											if Ag.Drawings[kg .. "Bar"] then
																																																												Ag.Drawings[kg .. "Bar"].Visible = false
																																																												Ag.Drawings[kg .. "Outline"].Visible = false
																																																												Ag.Drawings[kg .. "Text"].Visible = false
																																																											end
																																																										end
																																																										local function Ag(kg, xg, Rg, Ug, ig, og, Hg, Tg, Kg)
																																																											local Dg = math.clamp(ig / math.max(og, 1), 0, 1)
																																																											local og = Tg < 0 and Rg.X - (Kg + 1) * 7 or Rg.X + Ug.X + 4 + Kg * 7
																																																											local Tg = Jg(kg, xg .. "Outline", "Square", { Thickness = 1, Filled = true, Color = Color3.new(0.05, 0.05, 0.05) })

																																																											Tg.Position = Mg(og - 1, Rg.Y - 1)
																																																											Tg.Size = Mg(5, Ug.Y + 2)
																																																											Tg.Visible = true

																																																											local Tg = Jg(kg, xg .. "Bar", "Square", { Thickness = 1, Filled = true })
																																																											local Og = Ug.Y * Dg

																																																											Tg.Position = Mg(og, Rg.Y + (Ug.Y - Og))
																																																											Tg.Size = Mg(3, Og)
																																																											Tg.Color = Hg
																																																											Tg.Visible = true

																																																											local Tg = sg(kg, xg .. "Text", math.floor(mg.TextSize * 1.15), { Center = true, Outline = true, OutlineColor = Color3.new(0.05, 0.05, 0.05) })

																																																											Tg.Text = tostring(math.floor(ig))
																																																											Tg.Color = Hg
																																																											Tg.Position = Kg == 0 and Mg(og + 1.5, Rg.Y - Tg.TextBounds.Y - 2) or Mg(og + 1.5, Rg.Y + Ug.Y + 2)
																																																											Tg.Visible = true
																																																										end
																																																										local function kg(xg, Rg, Ug, ig, og, Hg, Tg)
																																																											local Kg = math.clamp(og / math.max(Hg, 1), 0, 1)
																																																											local Hg = Ug.Y + ig.Y + 4
																																																											local Dg = Jg(xg, Rg .. "Outline", "Square", { Thickness = 1, Filled = true, Color = Color3.new(0.05, 0.05, 0.05) })

																																																											Dg.Position = Mg(Ug.X - 1, Hg - 1)
																																																											Dg.Size = Mg(ig.X + 2, 5)
																																																											Dg.Visible = true

																																																											local Dg = Jg(xg, Rg .. "Bar", "Square", { Thickness = 1, Filled = true })

																																																											Dg.Position = Mg(Ug.X, Hg)
																																																											Dg.Size = Mg(ig.X * Kg, 3)
																																																											Dg.Color = Tg
																																																											Dg.Visible = true

																																																											local Jg = sg(xg, Rg .. "Text", math.floor(mg.TextSize * 1.15), { Center = true, Outline = true, OutlineColor = Color3.new(0.05, 0.05, 0.05) })

																																																											if not Fg(og) then
																																																												Jg.Visible = false

																																																												return Hg + 3 + 2
																																																											end

																																																											Jg.Text = tostring(math.floor(og))
																																																											Jg.Color = Tg
																																																											Jg.Position = Mg(Ug.X + ig.X / 2, Hg + 3 + 2)
																																																											Jg.Visible = true

																																																											return Hg + 3 + 2 + Jg.TextBounds.Y
																																																										end
																																																										local function Jg(xg, Rg, Ug, ig, og)
																																																											local Hg = sg(xg, "Race", mg.TextSize, { Center = false, Outline = true, OutlineColor = Color3.new(0.05, 0.05, 0.05) })

																																																											Hg.Text = ig
																																																											Hg.Color = og
																																																											Hg.Position = Mg(Rg.X + Ug.X + 4 + 3 + 4, Rg.Y)
																																																											Hg.Visible = true
																																																										end
																																																										local function xg(Rg, Ug, ig, og, Hg, Tg)
																																																											local Kg = sg(Rg, "Item", math.floor(mg.TextSize * 2), { Center = true, Outline = true, OutlineColor = Color3.new(0.05, 0.05, 0.05) })

																																																											Kg.Text = Hg
																																																											Kg.Color = Tg
																																																											Kg.Position = Mg(Ug.X + ig.X / 2, og + 2)
																																																											Kg.Visible = true
																																																										end
																																																										local function Rg(Ug, ig, og, Hg)
																																																											local Tg = 0

																																																											for Kg = #ig, 1, -1.0 do
																																																												local Dg = sg(Ug, "Text" .. Kg, mg.TextSize, { Center = true, Outline = true, OutlineColor = Color3.new(0.05, 0.05, 0.05) })

																																																												Dg.Text = tostring(ig[Kg])
																																																												Dg.Color = Hg
																																																												Tg = Tg + Dg.TextBounds.Y
																																																												Dg.Position = Mg(og.X, og.Y - Tg)
																																																												Dg.Visible = true
																																																											end

																																																											local sg = #ig + 1

																																																											while Ug.Drawings["Text" .. sg] do
																																																												Ug.Drawings["Text" .. sg].Visible = false
																																																												sg = sg + 1
																																																											end
																																																										end
																																																										local function sg(Ug)
																																																											local ig = Ug.Target
																																																											local og = Ug.Settings

																																																											if jg(og.Enabled, ig) == false then
																																																												cg(Ug)

																																																												return
																																																											end

																																																											local Hg = s(ig)

																																																											if not Hg then
																																																												cg(Ug)

																																																												return
																																																											end

																																																											local s = math.floor((k.CFrame.Position - Hg.Position).Magnitude)
																																																											local Tg = jg(og.MaxDistance, ig) or 1000

																																																											if s > Tg then
																																																												cg(Ug)

																																																												return
																																																											end

																																																											if mg.VisCheck and not Gg(ig, Hg.Position) then
																																																												cg(Ug)

																																																												return
																																																											end

																																																											local Gg = jg(og.Color, ig) or Color3.new(1, 1, 1)
																																																											local Tg = jg(og.Transparency, ig) or 1
																																																											local Kg, Dg = Pg(Hg.Position)

																																																											eg(Ug, Kg, Gg, s, Tg)

																																																											if not Dg then
																																																												for Pg, eg in pairs(Ug.Drawings) do
																																																													if Pg ~= "Tracer" and Pg ~= "TracerOutline" then
																																																														eg.Visible = false
																																																													end
																																																												end

																																																												return
																																																											end

																																																											local Pg = Kg
																																																											local eg, Hg

																																																											if jg(og.Box, ig) then
																																																												eg, Hg = lg(Ug, ig, Gg, og)

																																																												if eg then
																																																													Pg = Mg(eg.X + Hg.X / 2, eg.Y)
																																																												end
																																																											elseif Ug.Drawings.Box then
																																																												Ug.Drawings.Box.Visible = false
																																																												Ug.Drawings.BoxOutline.Visible = false
																																																											end

																																																											local lg, Kg = jg(og.Health, ig)

																																																											if eg and type(lg) == "number" then
																																																												Kg = Kg or 100

																																																												local Dg = math.clamp(lg / math.max(Kg, 1), 0, 1)

																																																												Ag(Ug, "Health", eg, Hg, lg, Kg, rg:Lerp(Ig, Dg), -1.0, 0)
																																																											else
																																																												Qg(Ug, "Health")
																																																											end

																																																											local lg, Kg = jg(og.Hunger, ig)
																																																											local Dg = eg and eg.Y + Hg.Y or 0

																																																											if eg and type(lg) == "number" then
																																																												Dg = kg(Ug, "Hunger", eg, Hg, lg, Kg or 100, Lg)
																																																											else
																																																												Qg(Ug, "Hunger")
																																																											end

																																																											local lg = jg(og.Item, ig)

																																																											if eg and type(lg) == "string" and lg ~= "" then
																																																												xg(Ug, eg, Hg, Dg, lg, Gg)
																																																											elseif Ug.Drawings.Item then
																																																												Ug.Drawings.Item.Visible = false
																																																											end

																																																											local lg, kg = jg(og.Mana, ig)

																																																											if eg and type(lg) == "number" then
																																																												Ag(Ug, "Mana", eg, Hg, lg, kg or 100, qg, 1, 0)
																																																											else
																																																												Qg(Ug, "Mana")
																																																											end

																																																											local lg = jg(og.Race, ig)

																																																											if eg and type(lg) == "string" and lg ~= "" then
																																																												Jg(Ug, eg, Hg, lg, Gg)
																																																											elseif Ug.Drawings.Race then
																																																												Ug.Drawings.Race.Visible = false
																																																											end

																																																											local eg = jg(og.Text, ig, s)

																																																											if type(eg) == "string" then
																																																												eg = { eg }
																																																											end

																																																											if type(eg) ~= "table" or #eg == 0 then
																																																												eg = { string.format("[%s] [%s]", ig.Name, s) }
																																																											end

