																																																													Pg.Transparency = Tg
																																																												end
																																																											end
																																																										end

																																																										function mg.Add(s, Pg)
																																																											if not s or mg.Objects[s] then
																																																												return mg.Objects[s]
																																																											end

																																																											mg.Objects[s] = { Target = s, Settings = Pg or {}, Drawings = {} }

																																																											return mg.Objects[s]
																																																										end
																																																										function mg.Remove(s)
																																																											local Pg = mg.Objects[s]

																																																											if not Pg then
																																																												return
																																																											end

																																																											for eg, jg in pairs(Pg.Drawings) do
																																																												jg.Visible = false
																																																												jg:Remove()
																																																												Pg.Drawings[eg] = nil
																																																											end

																																																											mg.Objects[s] = nil
																																																										end
																																																										function mg.Clear()
																																																											for s in pairs(mg.Objects) do
																																																												mg.Remove(s)
																																																											end
																																																										end
																																																										function mg.Update()
																																																											local s = tick()

																																																											if s - Ng < mg.RefreshRate / 1000 then
																																																												return
																																																											end

																																																											Ng = s

																																																											for s, Ng in pairs(mg.Objects) do
																																																												if not s.Parent then
																																																													mg.Remove(s)
																																																												else
																																																													sg(Ng)
																																																												end
																																																											end
																																																										end
																																																										function mg.Start()
																																																											if mg.Running then
																																																												return
																																																											end

																																																											mg.Running = true
																																																											M:BindToRenderStep("RogueLineageESP", Enum.RenderPriority.Camera.Value + 1, mg.Update)
																																																										end
																																																										function mg.Stop()
																																																											if not mg.Running then
																																																												return
																																																											end

																																																											mg.Running = false
																																																											M:UnbindFromRenderStep("RogueLineageESP")

																																																											for s, s in pairs(mg.Objects) do
																																																												cg(s)
																																																											end
																																																										end

																																																										f:GiveSignal(u:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
																																																											if u.CurrentCamera then
																																																												k = u.CurrentCamera
																																																												Cg = k.WorldToViewportPoint
																																																											end
																																																										end))
																																																									end

