    local function isRoot(o) return (o.Name == "FoundationOverlay" or o.Name == "PurchasePromptApp") and o:IsA("LayerCollector") end
    local function hold(o, prop, val)
        local p = held[o]; if not p then p = {}; held[o] = p end
        local st = p[prop]
        if not st then
            local ok, orig = pcall(function() return o[prop] end); if not ok then return end
            st = { original = orig, value = val }; p[prop] = st
            if not pcall(function() o[prop] = val end) then p[prop] = nil; return end
            pconns[#pconns + 1] = o:GetPropertyChangedSignal(prop):Connect(function()
                if not holding or not o.Parent then return end
                pcall(function() if o[prop] ~= st.value then o[prop] = st.value end end)
            end)
        else st.value = val; pcall(function() o[prop] = val end) end
    end
    local function conceal(o)
        if o:IsA("GuiObject") then hold(o, "BackgroundTransparency", 1); hold(o, "BorderSizePixel", 0) end
        if o:IsA("TextLabel") or o:IsA("TextButton") or o:IsA("TextBox") then hold(o, "TextTransparency", 1); hold(o, "TextStrokeTransparency", 1) end
        if o:IsA("ImageLabel") or o:IsA("ImageButton") then hold(o, "ImageTransparency", 1) end
        if o:IsA("ScrollingFrame") then hold(o, "ScrollBarImageTransparency", 1) end
        if o:IsA("CanvasGroup") then hold(o, "GroupTransparency", 1) end
        if o:IsA("UIStroke") then hold(o, "Transparency", 1); hold(o, "Enabled", false) end
        if o:IsA("UIGradient") then hold(o, "Enabled", false) end
    end
    local function forceConceal()
        if not holding then return end
        for root in pairs(roots) do if root.Parent then for _, o in ipairs(root:GetDescendants()) do
            local p = held[o]
            if p then for prop, st in pairs(p) do pcall(function() if o[prop] ~= st.value then o[prop] = st.value end end) end else conceal(o) end
        end end end
    end
    local function watch(root)
        if roots[root] then return end
        roots[root] = true
        for _, o in ipairs(root:GetDescendants()) do conceal(o); if o.Name == "Sheet" and not live.sheet then live.overlay, live.sheet = root, o end end
        rconns[#rconns + 1] = root.DescendantAdded:Connect(function(o) conceal(o); if o.Name == "Sheet" and not live.sheet then live.overlay, live.sheet = root, o end end)
    end
    local function release()
        holding = false
        pcall(function() RunService:UnbindFromRenderStep(renderKey) end)
        for _, cn in ipairs(rconns) do pcall(function() cn:Disconnect() end) end
        for _, cn in ipairs(pconns) do pcall(function() cn:Disconnect() end) end
        for o, p in pairs(held) do if o.Parent then for prop, st in pairs(p) do pcall(function() o[prop] = st.original end) end end end
    end
    -- ALL VIM input here needs +GuiInset, and a MOVE must precede the press or the
    -- button stays Idle. Measured 2026-07-24 by hover-sweeping the live sheet; see
    -- Docs/Ro Sec/PLS DONATE purchase-completion-findings.md. Raw coords land 58px
    -- high -- on the Backdrop (which dismisses, hiding the bug) and 58px above the
    -- 40px-tall BuyButton, so a raw Buy click NEVER fires.
    --
    -- The move stays. The YIELDS between the three events are gone, measured
    -- 2026-07-26: with 0.06s gaps, moving the real cursor during the gap killed
    -- 10/10 clicks on a probe button; with all three events in one frame the same
    -- interference killed 0/10. The gap is the vulnerability, not the movement --
    -- a person moving their mouse mid-purchase re-resolves hover and the press
    -- lands on nothing, and this whole path runs under a cover where they cannot
    -- see why. Same-frame is equal undisturbed (3/3 on the live prompt tree for
    -- both shapes, X-button dismissals) and immune to that.
    --
    -- GuiState only reaches Hover a frame AFTER the move (Idle same-frame,
    -- measured on the live BuyButton), which looks like it should break this --
    -- it does not. GuiState is the visual state; the press resolves its target at
    -- press time and does not wait for it to catch up.
    local function clickAt(x, y)
        VIM:SendMouseMoveEvent(x, y, game)
        VIM:SendMouseButtonEvent(x, y, 0, true, game, 1)
        VIM:SendMouseButtonEvent(x, y, 0, false, game, 1)
    end
    -- Coords are relative to the element's own LayerCollector origin. The overlay
    -- and the shop are ScreenGuis with IgnoreGuiInset=true (AbsolutePosition
    -- 0,-58), so this reproduces "+GuiInset" exactly -- but deriving it from the
    -- root stays correct at any resolution, with the topbar hidden, and if
    -- IgnoreGuiInset ever flips to false (where adding the inset would be WRONG).
    local function click(g)
        local root = g:FindFirstAncestorWhichIsA("LayerCollector")
        local ox, oy = 0, 0
        if root then ox, oy = root.AbsolutePosition.X, root.AbsolutePosition.Y end
        local p, s = g.AbsolutePosition, g.AbsoluteSize
        clickAt(math.floor(p.X + s.X / 2) - ox, math.floor(p.Y + s.Y / 2) - oy)
    end
    local function safeProp(object, property)
        if not object then return "n/a" end
        local ok, value = pcall(function() return object[property] end)
        return ok and tostring(value) or ("unreadable:" .. tostring(value))
    end
    -- Prefer the named BuyButton: that is what the one manual click that DID
    -- complete a real purchase used. Walking up from the "Buy" label lands on the
    -- 456x80 "Actions" wrapper rather than the 416x40 BuyButton, so it stays a
    -- fallback only.
    local function findBuy(sheet)
        local named = sheet:FindFirstChild("BuyButton", true)
        if named and named:IsA("GuiButton") and named.AbsoluteSize.X > 0 then return named end
        for _, o in ipairs(sheet:GetDescendants()) do
            if o:IsA("TextLabel") and tostring(o.Text) == "Buy" then
                local c = o.Parent; while c and c ~= sheet do if c:IsA("GuiButton") then return c end; c = c.Parent end
            end
        end
    end
    -- The "Buy Robux and item" UPSELL sheet carries NO node named BuyButton, so on it
    -- the walk-up fallback above is the only thing that can match -- and the button it
    -- returns opens a REAL-MONEY card web view. Measured 2026-07-26: that view is not a
    -- GuiObject so Lua cannot see or dismiss it, Escape only opens the Roblox menu, and
    -- it SURVIVES a rejoin; a human had to close it by hand while the un-dismissed
    -- upsell hard-blocked every later prompt-open. Detect it by its currency-bearing
    -- RobuxPrice: a genuine product sheet's only RobuxPrice is the plain-number header
    -- balance (that is the same "$" tell sheetBalance already relies on).
    local function isUpsellSheet(sheet)
        if not sheet then return false end
        for _, o in ipairs(sheet:GetDescendants()) do
            if o.Name == "RobuxPrice" and (o:IsA("TextLabel") or o:IsA("TextButton"))
                and tostring(o.Text):find("%$") then
                return true
            end
        end
        return false
    end
    -- The sheet carries TWO nodes named CloseAffordance, and they are DIFFERENT
    -- components: the real X lives in Sheet>Content>Header>Content; the other is a
    -- DECOY parented directly under Sheet -- Visible=false in steady state (77/77
    -- samples on the live PLS DONATE Product_2 sheet, 2026-07-26) yet still
    -- Interactable=true, so only Visible tells them apart, and Visible=false does
    -- not zero AbsoluteSize. Which one FindFirstChild returns depends on Sheet
    -- child order, and the captures show that order is NOT stable across sessions
    -- (it returned the real X in one, the decoy in the other). Tap-instrumented
    -- live on the same sheet: a VIM click at the decoy's centre fired the REAL
    -- X's Activated -- the 40x40 rects overlap 28x28 there and invisible
    -- GuiObjects receive no input (the decoy never appears in
    -- GetGuiObjectsAtPosition); a click inside the decoy-only strip fired
    -- NOTHING and the sheet STAYED UP, because Sheet is itself an ImageButton
    -- and sinks the click -- it does not even fall through to the Backdrop. So
    -- aiming at the decoy works only while the rects happen to overlap; nothing
    -- ties the decoy's geometry to the real X (under a Visible=false hold it
    -- reflowed 464px away), and a separated miss leaves the prompt up -- which
    -- survives teleports and blocks every later open, the documented
    -- stuck-until-rejoin failure.
    -- Pick on Visible (ancestor chain included), and keep the old selector as a
    -- fallback so a variant that hides both is still dismissed rather than left up.
    local function closeAffordance(root)
        if not root then return nil end
        for _, o in ipairs(root:GetDescendants()) do
            if o.Name == "CloseAffordance" and o:IsA("GuiObject")
                and o.Visible and o.AbsoluteSize.X > 0 then
                local shown, c = true, o.Parent
                while c and c ~= root do
                    if c:IsA("GuiObject") and not c.Visible then shown = false; break end
                    c = c.Parent
                end
                if shown then return o end
            end
        end
        local any = root:FindFirstChild("CloseAffordance", true)
        if any and any:IsA("GuiObject") and any.AbsoluteSize.X > 0 then return any end
        return nil
    end
    -- Everything the sheet is actually showing, for the log. The click is invisible
    -- (concealed + no console), so this is the only way to tell a real product
    -- sheet from a stale one and a landed click from a missed one.
    local function sheetInfo(sheet)
        local bits = {}
        for _, o in ipairs(sheet:GetDescendants()) do
            if o:IsA("TextLabel") or o:IsA("TextButton") then
                local t = tostring(o.Text):gsub("<.->", "")
                if #t > 0 and #t < 40 then bits[#bits + 1] = o.Name .. "=" .. t end
                if #bits >= 8 then break end
            end
        end
        return table.concat(bits, " | ")
    end
    -- The prompt's ModalHeader carries the LIVE Robux balance, and it is the only
    -- ground truth this leg has: Roblox reports purchased=false on purchases that
    -- DID debit, the in-experience topbar carries no Robux label, and
    -- GetRobuxBalance is identity-gated. Mirrors readBal in the Hoopz leg,
    -- including the "$" skip -- the upsell sheet prints a CURRENCY price under the
    -- same node name, which is a price, not a balance.
    local function sheetBalance(root)
        if not root then return nil end
        local fb
        for _, o in ipairs(root:GetDescendants()) do
            if o.Name == "RobuxPrice" and (o:IsA("TextLabel") or o:IsA("TextButton")) then
                local s = tostring(o.Text):gsub("<.->", "")
                if not s:find("%$") then
                    local v = s:match("[%d,]+")
                    local b = v and tonumber((v:gsub(",", "")))
                    if b then
                        local c = o.Parent
                        while c and c ~= root do
                            if c.Name == "ModalHeader" or c.Name == "Header" then return b end
                            c = c.Parent
                        end
                        if not fb then fb = b end
                    end
                end
            end
        end
        return fb
    end
    -- The affordable Foundation sheet exposes the actual charge in ItemCost
    -- (measured as "robux 2" for Product_2). Validate this rendered value rather
    -- than trusting the shop button's Product_N name to remain correctly wired.
    local function sheetLabelPrice(root, labelName)
        local found
        for _, o in ipairs(root:GetDescendants()) do
            if o.Name == labelName
                and (o:IsA("TextLabel") or o:IsA("TextButton")) then
                local text = tostring(o.Text):gsub("<.->", "")
                local digits = text:match("[%d,]+")
                local value = digits and tonumber((digits:gsub(",", "")))
                if value then
                    if found and found ~= value then
                        return nil, ("ambiguous:%d,%d"):format(found, value)
                    end
                    found = value
                end
            end
        end
        return found, found and labelName or (labelName .. "-missing")
    end
    -- A DISCOUNTED sheet renders BOTH prices: OriginalPrice is the list price the
    -- plan was built from, ItemCost the smaller amount actually charged. Measured
    -- 2026-08-04 on a live buyer's Premium account -- Product_10 came back
    -- OriginalPrice="robux 10" ItemCost="robux 9" LeadingIcon="roblox-plus" --
    -- and comparing that 9 against the planned 10 refused a perfectly good Buy.
    -- OriginalPrice is absent at full price, so its presence IS the discount
    -- marker; nothing here needs to know why the price dropped or by how much.
    local function sheetItemPrice(root)
        if not root then return nil, "sheet-missing" end
        local charge, source = sheetLabelPrice(root, "ItemCost")
        local list = sheetLabelPrice(root, "OriginalPrice")
        return charge, source, list
    end
    local function gone() return not live.overlay or not live.overlay.Parent or not live.overlay:FindFirstChild("Sheet", true) end
    local function upsell() local a = CoreGui:FindFirstChild("PurchasePromptApp"); return a and a:FindFirstChild("RobuxUpsellContainer", true) end
    local function dismissAlert()
        local u = upsell(); if not u then return end
        for _, d in ipairs(u:GetDescendants()) do
            if d:IsA("GuiButton") and d.AbsoluteSize.X > 50 and d.AbsoluteSize.Y > 2 and d.AbsoluteSize.Y < 80 then
                for _, t in ipairs(d:GetDescendants()) do
                    if t:IsA("TextLabel") and tostring(t.Text) == "Ok" then
                        click(d); return
                    end
                end
            end
        end
    end

    local purchaseFinishedCount = 0
    local lastPurchaseFinished = "none"
    local purchaseFinishedConn
    local signalWatchOk, signalWatchError = pcall(function()
        purchaseFinishedConn = MPS.PromptProductPurchaseFinished:Connect(
            function(userId, productId, purchased)
                purchaseFinishedCount = purchaseFinishedCount + 1
                lastPurchaseFinished = ("userId=%s productId=%s purchased=%s")
                    :format(tostring(userId), tostring(productId), tostring(purchased))
                plog(
                    ("event=%d %s"):format(purchaseFinishedCount, lastPurchaseFinished),
                    "purchase-finished-signal",
                    purchased and "success"
                        or (MODE == "spend" and "error" or "info")
                )
            end
        )
    end)
    plog(
        signalWatchOk
            and "PromptProductPurchaseFinished observer connected."
            or ("PromptProductPurchaseFinished observer failed: "
                .. tostring(signalWatchError)),
        "purchase-signal-watch",
        signalWatchOk and "success" or "error"
    )

    for _, c in ipairs(CoreGui:GetChildren()) do if isRoot(c) then watch(c) end end
    local coreConn = CoreGui.DescendantAdded:Connect(function(o) if isRoot(o) then watch(o) end end)
    RunService:BindToRenderStep(renderKey, Enum.RenderPriority.Last.Value + 30000, forceConceal)

    -- settlePrice/settleFrom describe a previous purchase whose confirmation never
    -- rendered: its price, and the balance we held before it. Passed in so the
    -- header read below can wait for that debit to show up instead of reading once.
    local function doOne(product, expectedPrice, settlePrice, settleFrom, expectedBalance)
        local purchaseStarted = os.clock()
        local signalCountBefore = purchaseFinishedCount
        live.overlay, live.sheet = nil, nil
        local btn = grid:FindFirstChild(product)
        if not (btn and btn:IsA("GuiButton") and btn.AbsoluteSize.X > 0) then
            plog(
                ("product=%s button=%s class=%s size=%s")
                    :format(
                        tostring(product),
                        tostring(btn ~= nil),
                        safeProp(btn, "ClassName"),
                        safeProp(btn, "AbsoluteSize")
                    ),
                "purchase-button-missing",
                "error"
            )
            return false, "no-button"
        end
        local t = os.clock()
        local openAttempt = 0
        while not live.sheet and openAttempt < 3 and os.clock() - t < 12 do
            openAttempt = openAttempt + 1
            local currentButton = grid:FindFirstChild(product)
            if currentButton and currentButton:IsA("GuiButton") then
                btn = currentButton
            end
            click(btn)
            plog(
                ("product=%s attempt=%d clickSent=true state=%s pos=%s size=%s")
                    :format(
                        tostring(product),
                        openAttempt,
                        tostring(btn.GuiState),
                        tostring(btn.AbsolutePosition),
                        tostring(btn.AbsoluteSize)
                    ),
                "purchase-open-click",
                "info"
            )
            local attemptDeadline = math.min(t + 12, os.clock() + 4)
            while not live.sheet and os.clock() < attemptDeadline do
                task.wait(0.05)
            end
        end
        while not (live.sheet and findBuy(live.sheet)) and os.clock() - t < 12 do task.wait(0.05) end
        if not live.sheet then
            -- A refusal raises the "Error" alert INSTEAD of the Sheet. Left up it
            -- hard-blocks every later prompt-open and becomes visible once conceal
            -- releases, so clear it before reporting the refusal.
            local ta = os.clock()
            while upsell() and os.clock() - ta < 5 do dismissAlert(); task.wait(0.35) end
            plog(
                ("product=%s attempts=%d wait=%.2fs overlay=%s alert=%s signalDelta=%d lastSignal=%s")
                    :format(
                        tostring(product),
                        openAttempt,
                        os.clock() - t,
                        tostring(live.overlay ~= nil and live.overlay.Parent ~= nil),
                        tostring(upsell() ~= nil),
                        purchaseFinishedCount - signalCountBefore,
                        lastPurchaseFinished
                    ),
                "purchase-sheet-timeout",
                "error"
            )
            return false, "no-sheet"
        end
        local buy = findBuy(live.sheet)
        plog(
            ("product=%s wait=%.2fs buyFound=%s gone=%s labels=%s")
                :format(
                    tostring(product),
                    os.clock() - t,
                    tostring(buy ~= nil),
                    tostring(gone()),
                    sheetInfo(live.sheet)
                ),
            "purchase-sheet-ready",
            buy and "success" or "error"
        )
        -- Read at mount, so it reflects the balance AFTER the previous purchase --
        -- which is exactly what settles one whose confirmation never rendered.
        local headerBalance = sheetBalance(live.overlay or live.sheet)
        -- WARNING: this loop CANNOT refresh a stale header. MEASURED 2026-07-26 --
        -- the header balance is fixed when the sheet mounts and never updates in
        -- place: polled on one open sheet for 12.14s it did not move off the
        -- pre-purchase value. Re-reading the sheet we already hold is therefore
        -- inert, and it is kept only because it costs nothing and still guards the
        -- case where the value simply had not rendered on the first read.
        -- Freshness comes from somewhere else entirely: the PREVIOUS prompt must be
        -- dismissed with its CloseAffordance so this sheet remounts (see the
        -- confirmation dismissal below). Do not add time here expecting it to help.
        local settleWait = 0
        if settlePrice and settleFrom and headerBalance
            and headerBalance > settleFrom - settlePrice then
            local tb = os.clock()
            while os.clock() - tb < 6 do
                task.wait(0.25)
                local b = sheetBalance(live.overlay or live.sheet)
                if b then
                    headerBalance = b
                    if b <= settleFrom - settlePrice then break end
                end
            end
            settleWait = os.clock() - tb
        end
        plog(
            ("product=%s headerBalance=%s settleWait=%.2fs")
                :format(tostring(product), tostring(headerBalance), settleWait),
            "purchase-sheet-balance",
            headerBalance and "info" or "error"
        )
        local function rejectBeforeBuy(reason, stage, detail)
            plog(detail, stage, "error")
            local td = os.clock()
            while os.clock() - td < 5 do
                if upsell() then dismissAlert() end
                if not gone() then
                    local close = closeAffordance(live.overlay)
                    if close then click(close) end
                end
                task.wait(0.2)
                if gone() and not upsell() then break end
            end
            plog(
                ("product=%s reason=%s cleared=%s wait=%.2fs")
                    :format(
                        tostring(product),
                        tostring(reason),
                        tostring(gone() and not upsell()),
                        os.clock() - td
                    ),
                "purchase-preflight-cleanup",
                gone() and not upsell() and "success" or "error"
            )
            return false, reason, headerBalance
        end

        -- A sheet opened in this VM is the live source of truth. Before any Buy
        -- input, require its header to agree with the ledger. If the previous
        -- purchase was unconfirmed, only its exact debit is safe to continue;
        -- an unchanged balance is remounted once by the caller before being
        -- treated as a refusal. Normal confirmed runs take this branch with no
        -- wait because headerBalance was already read above.
        if MODE == "spend" then
            if not headerBalance then
                return rejectBeforeBuy(
                    "balance-unreadable",
                    "purchase-balance-preflight",
                    ("product=%s expected=%s actual=nil -- refusing Buy")
                        :format(tostring(product), tostring(expectedBalance))
                )
            end
            local previousDebitBalance = settlePrice
                and expectedBalance
                and (expectedBalance - settlePrice)
                or nil
            if settlePrice and headerBalance == expectedBalance then
                return rejectBeforeBuy(
                    "balance-unsettled",
                    "purchase-balance-preflight",
                    ("product=%s expectedPreviousDebit=%s actual=%d -- remount before deciding whether %s was refused")
                        :format(
                            tostring(product),
                            tostring(previousDebitBalance),
                            headerBalance,
                            tostring(settlePrice)
                        )
                )
            end
            if headerBalance ~= expectedBalance
                and headerBalance ~= previousDebitBalance then
                return rejectBeforeBuy(
                    "balance-mismatch",
                    "purchase-balance-preflight",
                    ("product=%s expected=%s previousDebit=%s actual=%d -- refusing Buy")
                        :format(
                            tostring(product),
                            tostring(expectedBalance),
                            tostring(previousDebitBalance),
                            headerBalance
                        )
                )
            end
        end
        -- Refuse the upsell sheet BEFORE any click. Gated on BOTH discriminators so a
        -- genuine sheet can never trip it: a real product sheet always carries a node
        -- named BuyButton (verified live 2026-07-26, ImageButton 416x40), so the "$"
        -- test is only ever consulted when that node is absent -- which is the upsell.
        -- Note this also stops MODE="attempt" from clicking Buy: attempt picks products
        -- ABOVE the balance, so it lands here every time, which is precisely how the
        -- real-money web view got opened. It still proves the plumbing (open, read
        -- balance, dismiss) -- it just no longer clicks the one button that can strand
        -- the client behind a payment page.
        if not live.sheet:FindFirstChild("BuyButton", true)
            and isUpsellSheet(live.overlay or live.sheet) then
            plog(
                ("product=%s is the Robux UPSELL sheet (no BuyButton, currency price present) -- refusing to click; that button opens a real-money web view Lua cannot close and a rejoin does not clear")
                    :format(tostring(product)),
                "purchase-upsell-refused",
                "error"
            )
            local tu = os.clock()
            while os.clock() - tu < 5 do
                if upsell() then dismissAlert() end
                if not gone() then
                    local close = closeAffordance(live.overlay)
                    if close then click(close) end
                end
                task.wait(0.35)
                if gone() and not upsell() then break end
            end
            return false, "upsell-sheet", headerBalance
        end
        local promptPrice, promptPriceSource, promptListPrice = sheetItemPrice(live.sheet)
        local priceWaitStarted = os.clock()
        while not promptPrice
            and not gone()
            and os.clock() - priceWaitStarted < 2 do
            task.wait(0.05)
            promptPrice, promptPriceSource, promptListPrice = sheetItemPrice(live.sheet)
        end
        local buttonPrice = tonumber(tostring(product):match("^Product_(%d+)$"))
        -- The plan was built from LIST prices, so the list price is what has to
        -- match it. An undiscounted sheet renders no OriginalPrice, in which case
        -- the charge is the list price.
        local listPrice = promptListPrice or promptPrice
        plog(
            ("product=%s expectedPrice=%s buttonPrice=%s promptPrice=%s originalPrice=%s source=%s wait=%.2fs")
                :format(
                    tostring(product),
                    tostring(expectedPrice),
                    tostring(buttonPrice),
                    tostring(promptPrice),
                    tostring(promptListPrice or "none"),
                    tostring(promptPriceSource),
                    os.clock() - priceWaitStarted
                ),
            "purchase-price-preflight",
            listPrice == expectedPrice
                and buttonPrice == expectedPrice
                and promptPrice ~= nil
                and promptPrice <= expectedPrice
                and "success" or "error"
        )
        if MODE == "spend" then
            if buttonPrice ~= expectedPrice then
                return rejectBeforeBuy(
                    "planned-price-mismatch",
                    "purchase-price-preflight-failed",
                    ("product=%s planned=%s buttonNamePrice=%s -- refusing Buy")
                        :format(
                            tostring(product),
                            tostring(expectedPrice),
                            tostring(buttonPrice)
                        )
                )
            end
            if not promptPrice then
                return rejectBeforeBuy(
                    "price-unreadable",
                    "purchase-price-preflight-failed",
                    ("product=%s planned=%s promptPrice=nil source=%s -- refusing Buy")
                        :format(
                            tostring(product),
                            tostring(expectedPrice),
                            tostring(promptPriceSource)
                        )
                )
            end
            -- Identity check: this is what stops a re-wired Product_N button from
            -- opening a different item than the plan asked for. The list price is
            -- immune to whatever discount the account carries, so it stays exact.
            if listPrice ~= expectedPrice then
                return rejectBeforeBuy(
                    "price-mismatch",
                    "purchase-price-preflight-failed",
                    ("product=%s planned=%d listPrice=%d charge=%d -- refusing Buy")
                        :format(product, expectedPrice, listPrice, promptPrice)
                )
            end
            -- Charge check: paying MORE than planned is the hazard -- it overdraws
            -- the budget and desyncs the ledger. Paying LESS is a discount and is
            -- safe, because the ledger below records what was actually charged
            -- rather than what was planned, so the balance still reconciles.
            if promptPrice > expectedPrice then
                return rejectBeforeBuy(
                    "price-over-plan",
                    "purchase-price-preflight-failed",
                    ("product=%s planned=%d charge=%d -- refusing Buy")
                        :format(product, expectedPrice, promptPrice)
                )
            end
        end
        if MODE == "probe" then
            -- read-only: report why a click would or would not take, then dismiss
